<?php

namespace App\Libraries;

final class PanelPhoto
{
    public static function resolve(string $base, int $company, string $relative): ?string
    {
        // Only the exact relative format generated by the ESP32 API is accepted.
        if (! preg_match('~\A' . $company . '/[a-f0-9]{32}\.jpg\z~D', $relative)) {
            return null;
        }
        $root = realpath($base);
        $path = realpath(rtrim($base, '/\\') . DIRECTORY_SEPARATOR . $relative);
        if ($root === false || $path === false || ! is_file($path) || ! is_readable($path)) {
            return null;
        }
        $prefix = $root . DIRECTORY_SEPARATOR . $company . DIRECTORY_SEPARATOR;
        // realpath also prevents symlinks from escaping the company's directory.
        return str_starts_with($path, $prefix) ? $path : null;
    }
}
